-- Fresh engine schema of the current (v1.80.x line) memory store; generated by scripts/capture_memory_schema.py.
-- memory-v1793.sql is the pinned older catalog and is never regenerated. Difference: RM-039 idx_memories_subject_ts.
CREATE TABLE IF NOT EXISTS memories (
                id TEXT PRIMARY KEY,
                agent_id TEXT NOT NULL,
                content TEXT NOT NULL,
                timestamp TEXT NOT NULL,
                tags TEXT NOT NULL DEFAULT '[]',
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                layer TEXT NOT NULL DEFAULT 'episodic',
                importance REAL NOT NULL DEFAULT 5.0,
                access_count INTEGER NOT NULL DEFAULT 0,
                last_accessed TEXT,
                source_event TEXT DEFAULT ''
            );

            CREATE INDEX IF NOT EXISTS idx_memories_agent
                ON memories(agent_id);

            CREATE INDEX IF NOT EXISTS idx_memories_timestamp
                ON memories(timestamp);

            CREATE INDEX IF NOT EXISTS idx_memories_layer
                ON memories(layer);

            CREATE INDEX IF NOT EXISTS idx_memories_importance
                ON memories(importance DESC);

            CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(
                content,
                agent_id UNINDEXED,
                memory_id UNINDEXED,
                tokenize='unicode61'
            );
CREATE TABLE IF NOT EXISTS key_facts (
                id TEXT PRIMARY KEY,
                agent_id TEXT NOT NULL,
                fact TEXT NOT NULL,
                channel TEXT DEFAULT '',
                chat_id TEXT DEFAULT '',
                source_session TEXT DEFAULT '',
                timestamp TEXT NOT NULL,
                access_count INTEGER DEFAULT 0
            );

            CREATE INDEX IF NOT EXISTS idx_facts_agent
                ON key_facts(agent_id, timestamp DESC);
CREATE VIRTUAL TABLE IF NOT EXISTS key_facts_fts USING fts5(
                fact,
                tokenize='unicode61'
            );
ALTER TABLE memories ADD COLUMN valid_from TEXT;
ALTER TABLE memories ADD COLUMN valid_until TEXT;
ALTER TABLE memories ADD COLUMN superseded_by TEXT;
ALTER TABLE memories ADD COLUMN supersedes TEXT;
ALTER TABLE memories ADD COLUMN subject TEXT;
ALTER TABLE memories ADD COLUMN predicate TEXT;
ALTER TABLE memories ADD COLUMN object TEXT;
ALTER TABLE memories ADD COLUMN confidence REAL NOT NULL DEFAULT 1.0;
ALTER TABLE memories ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}';
ALTER TABLE memories ADD COLUMN origin TEXT;
ALTER TABLE memories ADD COLUMN origin_trust REAL NOT NULL DEFAULT 1.0;
ALTER TABLE memories ADD COLUMN derived_from TEXT;
ALTER TABLE memories ADD COLUMN ingested_at TEXT;
ALTER TABLE memories ADD COLUMN invalidated_by_event TEXT;
ALTER TABLE memories ADD COLUMN invalidated_at TEXT;
ALTER TABLE memories ADD COLUMN embedding BLOB;
ALTER TABLE memories ADD COLUMN embedding_model TEXT;
ALTER TABLE memories ADD COLUMN quarantined INTEGER NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_memories_triple
                 ON memories(agent_id, subject, predicate) WHERE valid_until IS NULL;
             CREATE INDEX IF NOT EXISTS idx_memories_valid
                 ON memories(agent_id, valid_until);
CREATE INDEX IF NOT EXISTS idx_memories_subject_ts
                 ON memories(subject, timestamp DESC, id DESC);
CREATE TABLE IF NOT EXISTS entity_alias (
                agent_id TEXT NOT NULL,
                canonical TEXT NOT NULL,
                alias TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (agent_id, alias)
            );
            CREATE INDEX IF NOT EXISTS idx_entity_alias_agent
                ON entity_alias(agent_id);
CREATE TABLE IF NOT EXISTS entity_embedding (
                agent_id TEXT NOT NULL,
                entity TEXT NOT NULL,
                model TEXT NOT NULL,
                vec BLOB NOT NULL,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                PRIMARY KEY (agent_id, entity, model)
            );
CREATE TABLE IF NOT EXISTS memory_origins (
            memory_store       TEXT NOT NULL CHECK (memory_store IN ('memories','key_facts')),
            memory_id          TEXT NOT NULL,
            agent_id           TEXT NOT NULL,
            source_kind        TEXT NOT NULL,
            source_session     TEXT NOT NULL,
            source_message     TEXT NOT NULL DEFAULT '',
            source_seq         INTEGER,
            source_observed_at TEXT NOT NULL,
            source_hash        TEXT,
            role               TEXT NOT NULL CHECK (role IN ('direct','inherited','reaffirm')),
            via_memory_id      TEXT,
            created_at         TEXT NOT NULL,
            PRIMARY KEY (memory_store, memory_id, source_session, source_message)
        );
        CREATE INDEX IF NOT EXISTS idx_origins_source
            ON memory_origins(agent_id, source_session, source_message);
        CREATE INDEX IF NOT EXISTS idx_origins_seq
            ON memory_origins(agent_id, source_session, source_seq);
        CREATE INDEX IF NOT EXISTS idx_origins_memory
            ON memory_origins(memory_id);

        CREATE TABLE IF NOT EXISTS forgotten_sources (
            tombstone_id   TEXT PRIMARY KEY,
            agent_id       TEXT NOT NULL,
            source_session TEXT NOT NULL,
            scope          TEXT NOT NULL CHECK (scope IN ('message','session_upto')),
            source_message TEXT NOT NULL DEFAULT '',
            upto_seq       INTEGER,
            upto_time      TEXT,
            source_digest  TEXT NOT NULL,
            plan_id        TEXT NOT NULL,
            forgotten_at   TEXT NOT NULL
        );
        CREATE UNIQUE INDEX IF NOT EXISTS idx_forgotten_unique
            ON forgotten_sources(agent_id, source_session, scope, source_message,
                                 COALESCE(upto_seq, -1), COALESCE(upto_time, ''));
        CREATE INDEX IF NOT EXISTS idx_forgotten_lookup
            ON forgotten_sources(agent_id, source_session);

        CREATE TABLE IF NOT EXISTS forgotten_memories (
            memory_store TEXT NOT NULL,
            memory_id    TEXT NOT NULL,
            agent_id     TEXT NOT NULL,
            plan_id      TEXT NOT NULL,
            forgotten_at TEXT NOT NULL,
            PRIMARY KEY (memory_store, memory_id)
        );

        CREATE TABLE IF NOT EXISTS memory_fence (
            agent_id     TEXT PRIMARY KEY,
            forget_epoch INTEGER NOT NULL DEFAULT 0,
            updated_at   TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS memory_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

        -- Which conversation turn a user message started, recorded when one
        -- write carried both as direct sources (P2-B F1). A conversation-level
        -- fact, kept across namespaces and forgets: an employee dispatched
        -- from that turn records only the turn, and a forget of the message
        -- in its namespace reads the link from here.
        CREATE TABLE IF NOT EXISTS turn_message_links (
            source_session TEXT NOT NULL,
            user_message   TEXT NOT NULL,
            turn_message   TEXT NOT NULL,
            PRIMARY KEY (source_session, user_message, turn_message)
        );

        CREATE TABLE IF NOT EXISTS memory_forget_plans (
            plan_id        TEXT PRIMARY KEY,
            agent_id       TEXT NOT NULL,
            plan_hash      TEXT NOT NULL,
            plan_json      TEXT NOT NULL,
            forget_epoch   INTEGER NOT NULL,
            db_instance_id TEXT NOT NULL,
            created_at     TEXT NOT NULL,
            expires_at     TEXT NOT NULL,
            status         TEXT NOT NULL CHECK (status IN ('planned','applied','stale','expired')),
            applied_at     TEXT
        );
        CREATE TABLE IF NOT EXISTS memory_forget_steps (
            plan_id    TEXT NOT NULL,
            step       TEXT NOT NULL,
            target     TEXT NOT NULL,
            status     TEXT NOT NULL CHECK (status IN ('pending','done','failed')),
            attempts   INTEGER NOT NULL DEFAULT 0,
            last_error TEXT,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (plan_id, step, target)
        );

        CREATE TRIGGER IF NOT EXISTS trg_memories_forgotten_id BEFORE INSERT ON memories
        WHEN EXISTS (SELECT 1 FROM forgotten_memories
                     WHERE memory_store = 'memories' AND memory_id = NEW.id)
        BEGIN SELECT RAISE(ABORT, 'duduclaw:memory_forgotten'); END;

        CREATE TRIGGER IF NOT EXISTS trg_key_facts_forgotten_id BEFORE INSERT ON key_facts
        WHEN EXISTS (SELECT 1 FROM forgotten_memories
                     WHERE memory_store = 'key_facts' AND memory_id = NEW.id)
        BEGIN SELECT RAISE(ABORT, 'duduclaw:memory_forgotten'); END;
CREATE TRIGGER IF NOT EXISTS trg_origins_fence BEFORE INSERT ON memory_origins
         WHEN (EXISTS (SELECT 1 FROM forgotten_sources f
                  WHERE f.agent_id = NEW.agent_id AND f.source_session = NEW.source_session
                    AND f.scope = 'message' AND f.source_message = NEW.source_message)
          OR EXISTS (SELECT 1 FROM forgotten_sources f
                  WHERE f.agent_id = NEW.agent_id AND f.source_session = NEW.source_session
                    AND f.scope = 'session_upto' AND (
                          (NEW.source_seq IS NOT NULL AND f.upto_seq IS NOT NULL AND NEW.source_seq <= f.upto_seq
                           AND (f.upto_time IS NULL OR NEW.source_observed_at <= f.upto_time))
                       OR ((NEW.source_seq IS NULL OR f.upto_seq IS NULL)
                           AND f.upto_time IS NOT NULL AND NEW.source_observed_at <= f.upto_time))))
         BEGIN SELECT RAISE(ABORT, 'duduclaw:source_forgotten'); END;
CREATE TABLE IF NOT EXISTS memory_connector_stamps (
            memory_store TEXT NOT NULL CHECK(memory_store IN ('memories','key_facts')),
            memory_id TEXT NOT NULL, connector_ref TEXT NOT NULL, stamped_at TEXT NOT NULL,
            connector_observed_at TEXT NOT NULL DEFAULT '',
            PRIMARY KEY(memory_store,memory_id,connector_ref));
         CREATE INDEX IF NOT EXISTS idx_memory_connector_ref
            ON memory_connector_stamps(connector_ref,memory_store,memory_id);
         CREATE TABLE IF NOT EXISTS forgotten_connectors (
            agent_id TEXT NOT NULL, connector_ref TEXT NOT NULL, upto_time TEXT NOT NULL,
            plan_id TEXT NOT NULL, PRIMARY KEY(agent_id,connector_ref));
         CREATE TABLE IF NOT EXISTS memory_forget_apply_reports (
            plan_id TEXT PRIMARY KEY, report_json TEXT NOT NULL);
         CREATE TABLE IF NOT EXISTS disconnect_forget_batches (
            id TEXT PRIMARY KEY, connector_ref TEXT NOT NULL, display_name TEXT NOT NULL,
            created_at TEXT NOT NULL, expires_at TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'planned', approval_id TEXT, digest TEXT NOT NULL,
            approved_by TEXT, lease_holder TEXT, lease_until INTEGER NOT NULL DEFAULT 0,
            last_error TEXT);
         CREATE TABLE IF NOT EXISTS disconnect_forget_batch_plans (
            batch_id TEXT NOT NULL, agent_id TEXT NOT NULL, approved_plan_id TEXT NOT NULL,
            apply_plan_id TEXT, PRIMARY KEY(batch_id,agent_id));
         CREATE TABLE IF NOT EXISTS forget_receipts (
            id TEXT PRIMARY KEY, batch_id TEXT NOT NULL UNIQUE,
            completed_at TEXT NOT NULL, receipt_json TEXT NOT NULL);
DROP TRIGGER IF EXISTS trg_connector_stamp_fence;
                 DROP TRIGGER IF EXISTS trg_connector_stamp_update_fence;
                 DROP INDEX IF EXISTS idx_memory_connector_ref;
                 ALTER TABLE memory_connector_stamps RENAME TO memory_connector_stamps_legacy;
                 CREATE TABLE memory_connector_stamps (
                    memory_store TEXT NOT NULL CHECK(memory_store IN ('memories','key_facts')),
                    memory_id TEXT NOT NULL, connector_ref TEXT NOT NULL, stamped_at TEXT NOT NULL,
                    connector_observed_at TEXT NOT NULL DEFAULT '',
                    source_session TEXT NOT NULL, source_message TEXT NOT NULL,
                    role TEXT NOT NULL CHECK(role IN ('direct','inherited','reaffirm','unknown')),
                    PRIMARY KEY(memory_store,memory_id,connector_ref,source_session,source_message,role));
                 INSERT INTO memory_connector_stamps SELECT memory_store,memory_id,connector_ref,
                    stamped_at,connector_observed_at,'','','unknown' FROM memory_connector_stamps_legacy;
                 DROP TABLE memory_connector_stamps_legacy;
                 CREATE INDEX idx_memory_connector_ref
                    ON memory_connector_stamps(connector_ref,memory_store,memory_id);
ALTER TABLE disconnect_forget_batches ADD COLUMN attempt_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE disconnect_forget_batches ADD COLUMN next_attempt_at INTEGER NOT NULL DEFAULT 0;
ALTER TABLE disconnect_forget_batches ADD COLUMN retry_status TEXT;
CREATE INDEX IF NOT EXISTS idx_disconnect_forget_due
                ON disconnect_forget_batches(status,next_attempt_at,created_at);
             CREATE TABLE IF NOT EXISTS disconnected_connectors (
                connector_ref TEXT PRIMARY KEY, disconnected_at TEXT NOT NULL,
                revision TEXT NOT NULL DEFAULT '', verified INTEGER NOT NULL DEFAULT 0);
UPDATE memory_connector_stamps SET connector_observed_at=COALESCE(
                (SELECT MIN(o.source_observed_at) FROM memory_origins o
                 WHERE o.memory_store=memory_connector_stamps.memory_store AND o.memory_id=memory_connector_stamps.memory_id), stamped_at)
             WHERE connector_observed_at='';
             DROP TRIGGER IF EXISTS trg_connector_stamp_fence;
             CREATE TRIGGER trg_connector_stamp_fence BEFORE INSERT ON memory_connector_stamps
             WHEN EXISTS (
                SELECT 1 FROM memory_origins o JOIN forgotten_connectors f
                  ON f.agent_id=o.agent_id AND f.connector_ref=NEW.connector_ref
                WHERE o.memory_store=NEW.memory_store AND o.memory_id=NEW.memory_id
                  AND NEW.connector_observed_at <= f.upto_time)
             BEGIN SELECT RAISE(ABORT,'duduclaw:connector_forgotten'); END;
             CREATE TRIGGER IF NOT EXISTS trg_connector_stamp_update_fence BEFORE UPDATE ON memory_connector_stamps
             WHEN EXISTS (
                SELECT 1 FROM memory_origins o JOIN forgotten_connectors f
                  ON f.agent_id=o.agent_id AND f.connector_ref=NEW.connector_ref
                WHERE o.memory_store=NEW.memory_store AND o.memory_id=NEW.memory_id
                  AND NEW.connector_observed_at <= f.upto_time)
             BEGIN SELECT RAISE(ABORT,'duduclaw:connector_forgotten'); END;
             INSERT OR REPLACE INTO memory_meta(key,value) VALUES('connector_schema_version','4');
